package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.setting.Settings;

/**
 * A person on a sheet. {@code grade} (one of A, B or C) is the first grade they were given, which applies
 * from the beginning of time; {@code dated} are the grades given since, each from its date on, by date.
 * {@code version} is raised on every edit. {@code retiredFrom} is the date they are retired from (null when
 * not retired); a person with one set is retired at once, whatever the date. {@code holds} are their holds, by
 * from-date: their OPEN claims dated within one, unless bound by a statement, count in no live total.
 * {@code terms} are their own terms in days recorded from the beginning of time, which come before those of their grade
 * and of the sheet (null for none); {@code datedTerms} are their own terms recorded since, each from its date on, by date.
 * {@code contact} is their contact, trimmed and lower-cased (null for none); no two people on a sheet share one.
 * {@code aliases} are their aliases, sorted as names are compared (ignoring case).
 * {@code origin} is the id of the sheet they were transferred from (null when they were not transferred in).
 * {@code retirements} are their past retirements (each ended by unretiring them), by from-date.
 * {@code tags} are the tags they carry: trimmed, lower-cased, without repeats and sorted.
 * {@code snapshots} are the SNAPSHOTs written for them, oldest first.
 */
public record Person(long id, String sheetId, String name, String grade, long version, LocalDate retiredFrom,
        List<Hold> holds, List<DatedGrade> dated, Integer terms, String contact, List<String> aliases, String origin,
        List<Retirement> retirements, List<String> tags, List<Snapshot> snapshots, List<DatedTerms> datedTerms) {

    public Person with(PersonRequest request) {
        return new Person(id, sheetId, request.name(), grade, version + 1, retiredFrom, holds, dated,
                request.terms() == null ? null : Integer.valueOf(request.terms()), request.contact(), aliases, origin, retirements,
                request.tags() == null ? List.of() : List.of(request.tags().split(",")), snapshots, datedTerms);
    }

    /** The grade in force on the date: the one with the latest from-date on or before it, else the first grade. */
    public String gradeOn(LocalDate date) {
        String on = grade;
        for (DatedGrade d : dated) {
            if (!d.from().isAfter(date)) {
                on = d.grade();
            }
        }
        return on;
    }

    /** The person's own terms in force on the date: those with the latest from-date on or before it, else those from the beginning of time (null for none). */
    public Integer ownTermsOn(LocalDate date) {
        Integer on = terms;
        for (DatedTerms d : datedTerms) {
            if (!d.from().isAfter(date)) {
                on = d.terms();
            }
        }
        return on;
    }

    /** The terms in force on the date: the person's own then, else those of their grade then (else the sheet's). */
    public int termsOn(LocalDate date, Settings settings) {
        Integer own = ownTermsOn(date);
        return own != null ? own : settings.terms(sheetId, gradeOn(date), date);
    }

    /** Whether the person has any hold. */
    public boolean held() {
        return !holds.isEmpty();
    }

    /** Whether the date falls within any of the person's holds. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /** Whether the person's retirement date is reached on the date (it is on or after it). */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date != null && !date.isBefore(retiredFrom);
    }

    public boolean retired() {
        return retiredFrom != null;
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/**
 * A person as the screen sees it. {@code grade} is the grade in force on the sheet's today; {@code grades} are
 * all the grades they were given, by from-date (yyyy-mm-dd; null for the first, from the beginning of time).
 * {@code retiredFrom} is yyyy-mm-dd, null when not retired; {@code held} is whether they have any
 * hold; {@code holds} are their holds by from-date (yyyy-mm-dd; {@code to} null when it has no end).
 * {@code terms} are their own terms in days in force on the sheet's today, null for none; {@code termses} are all their own
 * terms recorded, by from-date (yyyy-mm-dd; null for those from the beginning of time; terms null for none); {@code contact} is their contact, null for none;
 * {@code aliases} are their aliases, sorted as names are compared; {@code clashing} is whether their name or an alias
 * is also a name or alias of someone else on the sheet's tree (see {@link People#clashing}); {@code origin} is the id of
 * the sheet they were transferred from, null when they were not transferred in; {@code retirements} are their past
 * retirements by from-date (yyyy-mm-dd, each to the day they were unretired); {@code tags} are their tags, sorted; {@code snapshots} are the SNAPSHOTs written for
 * them, oldest first (the day being left, yyyy-mm-dd, and their due-total then).
 */
public record PersonResponse(long id, String name, String grade, List<Graded> grades, long version,
        String retiredFrom, boolean held, List<Held> holds, Integer terms, String contact, List<String> aliases, boolean clashing,
        String origin, List<Retired> retirements, List<String> tags,
        List<Snapshotted> snapshots, List<Termed> termses) {

    public record Termed(String from, Integer terms) {
    }

    public record Graded(String from, String grade) {
    }

    public record Held(String from, String to) {
    }

    public record Retired(String from, String to) {
    }

    public record Snapshotted(String day, String dueTotal) {
    }

    public static PersonResponse from(Person person, LocalDate today) {
        return from(person, today, false);
    }

    public static PersonResponse from(Person person, LocalDate today, boolean clashing) {
        List<Graded> grades = new ArrayList<>();
        grades.add(new Graded(null, person.grade()));
        person.dated().forEach(d -> grades.add(new Graded(d.from().toString(), d.grade())));
        return new PersonResponse(person.id(), person.name(), person.gradeOn(today), grades, person.version(),
                person.retiredFrom() == null ? null : person.retiredFrom().toString(), person.held(),
                person.holds().stream().map(h -> new Held(h.from().toString(), h.to() == null ? null : h.to().toString()))
                        .toList(), person.ownTermsOn(today), person.contact(), person.aliases(), clashing, person.origin(),
                person.retirements().stream().map(r -> new Retired(r.from().toString(), r.to().toString())).toList(),
                person.tags(), person.snapshots().stream().map(s -> new Snapshotted(s.day().toString(), s.dueTotal())).toList(),
                termses(person));
    }

    /** All the person's own terms recorded, by from-date: first those from the beginning of time. */
    public static List<Termed> termses(Person person) {
        List<Termed> termses = new ArrayList<>();
        termses.add(new Termed(null, person.terms()));
        person.datedTerms().forEach(d -> termses.add(new Termed(d.from().toString(), d.terms())));
        return termses;
    }
}
