package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateWatch {
    public void validate(@RequestBody WatchRequest request, Out<WatchRequest> body) throws InvalidPersonException {
        if (request == null || request.watched() == null) {
            throw new InvalidPersonException("Say whether to watch.");
        }
        body.set(request);
    }
}
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class ApplyWatch {
    // Only a change is stored and recorded: watching a person already watched (or unwatching one not watched) does nothing.
    public void apply(@Val WatchRequest request, @Val Person person, Watches watches, ServerHttpConnection connection,
            Audit audit) throws InvalidPersonException {
        String user = Audit.user(connection).trim();
        if (user.isEmpty()) {
            throw new InvalidPersonException("Sign in to watch.");
        }
        boolean watched = watches.has(person.id(), user);
        if (request.watched() == watched) {
            return;
        }
        if (request.watched()) {
            watches.add(person.id(), user);
        } else {
            watches.remove(person.id(), user);
        }
        audit.record(Audit.line(request.watched() ? "PERSON_WATCHED" : "PERSON_UNWATCHED", person.sheetId(), user,
                "name=" + person.name()));
    }
}
import { useSyncExternalStore } from 'react';

// One refusal per person row, shared by every cell that acts on the person (statement, retire, hold), so
// the row shows a single `person-error` and the next action on the row, whichever cell takes it, clears the last one.
const errors = new Map<number, string>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function setError(personId: number, error: string) {
  if ((errors.get(personId) ?? '') === error) return;
  if (error) errors.set(personId, error);
  else errors.delete(personId);
  listeners.forEach((l) => l());
}

/** The person's refusal ('' when none) and its setter. */
export function usePersonError(personId: number): [string, (error: string) => void] {
  const error = useSyncExternalStore(subscribe, () => errors.get(personId) ?? '');
  return [error, (next) => setError(personId, next)];
}

